    k = 0
    while commands:
        if k == 0:
            l, r = commands.pop(0)
            if l < r:
                horses[l:r+1] = horses[l:r+1][::-1]
            else:
                return "No solution"
        elif k == 1:
            l, r = commands.pop(0)
            if l < r:
                horses[l:r+1].reverse()
            else:
                return "No solution"
        elif k == 2:
            if len(horses) % 2 == 0:
                return "No solution"
            pair = commands.pop(0)
            side = len(horses) // 2
            horses[0:side] += horses[side:]
            horses[0:side] = list(map(lambda x: horses[0] + x % side, horses[0:side]))
        elif k == 3:
