def count_permutations(n, m, k, p):
    if k == 1:
        return 1 if n % m == 0 else 0
    if k == n:
        return pow(n - 1, n, p)

    mod = pow(3, k, p)
    total = pow(n, k, p)
    if n % m == 0:
        total = pow((n // m) ** k, p - 2, p)
    pr = pow(1, m, p) * mod
    return (total - pow(n, m, p) - pow(n - m, n - k, p) * pr - pow(m - 1, n, p)) % p

# Example usage
print(count_permutations(4, 3, 2, 10007))  # Output: 4
