from collections import deque

def remove_substrings(s, k):
    n = len(s)
    positions = deque()
    smallest = deque()

    # Find positions to remove substrings
    for i in range(n-1, -1, -1):
        if i >= k-1:
            if positions:
                p = positions[0]
                if s[p] >= s[i]:
                    smallest.appendleft(s[i])
            else:
                smallest.appendleft(s[i])
        else:
            p = deque()
            for p_p in positions:
                left_pos, right_pos = n - i - 1, n - p_p - 1
                left_copy, right_copy = "", ""
                left_copy, right_copy = s[p_p], s[i]
                while (left_copy != "?" or right_copy != "?") and left_pos >= 0 and right_pos >= 0:
                    if left_pos > right_pos:
                        left_pos -= 1
                    elif left_pos < right_pos:
                        right_pos -= 1
                    else:    # Left equals right
                        if left_copy < right_copy:
                            left_copy = '?'
                        else:
                            right_copy = '?'
                        left_pos -= 1; right_pos -= 1
                left_pos = n - left_pos - 1
                right_pos = n - right_pos - 1
                if left_pos > right_pos:
                    left_pos = 0
                while left_pos <= right_pos:
                    smallest.append(s[i])
                    left_pos += 1; right_pos -= 1
                s[p] = '?'
            if p:
                positions.remove(p)
                positions.appendleft(p)
            else:
                positions.clear()
                positions.append(p)

    # Add remaining characters
    smallest.extend(filter(lambda c: c != '?', s))

    return ''.join(smallest)
