from heapq import *

def dijkstra(graph, start):
    n = len(graph)
    distances = [float('inf')] * n
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_city = heappop(priority_queue)

        if current_distance > distances[current_city]:
            continue

        for neighbor, weight in graph[current_city]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return distances

def solve(n, m, q, cities, roads, queries):
    graph = [[] for _ in range(n)]
    mapping = []

    for i in range(m):
        a, b = roads[i]
        graph[a-1].append((b-1, 1))
        graph[b-1].append((a-1, 1))

    for i in range(n):
        if i not in graph:
            graph[i] = [(i, 0)]

    # Building the bidirectional mapping
    for start in graph:
        for end in graph:
            if len(start) > len(end):
                bag = start
                start = end
                end = bag

    mapping = [(start, end) for start in sorted(graph) for end in sorted(graph) if len(start) != len(end)]

    # Building the reverse mapping
    for start, end in mapping:
        graph[end].append((start, 0))

    for i in range(n):
        if i not in graph:
            graph[i] = [(i, 0)]

    # Creating a reduced graph
    reduced_graph = {}
    for i in mapping:
        if i not in reduced_graph:
            reduced_graph[i] = graph[i][-1]
        else:
            reduced_graph.setdefault(i, max(graph[i][-1], reduced_graph[i]))

    for node in reduced_graph:
        for edge in reduced_graph[node]:
            if len(graph[node]) and edge[1] != 0 and edge[1] < graph[node][-1][1]:
                graph[node].append(edge)

    return reduced_graph  

def main():
