class Juniorious:
    def __init__(self, lst: List[int]):
        self.init_heap = lst[:]
        self.modification_requests = []
        self.current_mod_request = 0
        for i in range(len(lst)):
            add_item(self.modification_requests, lst[i])

    def handle_request1(self, r: int) -> List[int]:
        additions = [1 if i < r else 0 for i in range(len(self.init_heap))]
        for i in range(len(self.init_heap)):
            self.modification_requests[self.current_mod_request] += additions[i]
            self.current_mod_request = (self.current_mod_request + 1) % len(self.modification_requests)
            add_item(self.modification_requests, self.init_heap[i] + 1)
            self.init_heap[i] += 1

        return self.init_heap[:r][::-1]

    def handle_request2(self, r: int, x: int) -> List[int]:
        additions = [1 if i < r else 0 for i in range(len(self.init_heap))]
        sums = [0] * len(self.init_heap)
        for i in range(len(additions)):
            if additions[i] == 1:
                tally = sums[i] + self.init_heap[i]
                self.modification_requests[self.current_mod_request] += tally * additions[i]
                sums[i] += x
                self.current_mod_request = (self.current_mod_request + 1) % len(self.modification_requests)
                add_item(self.modification_requests, sums[i])
        return sums[:r][::-1]

    def handle_request3(self, i: int, r: int, x: int) -> int:
        additions = [1 if j >= i and j < r else 0 for j in range(len(self.init_heap))]
        for j in range(len(self.init_heap)):
            if additions[j] == 1:
                target = (x-1) // additions[j] + 1
                tally = sums[j] + self.init_heap[j]
                current = sums[j] + self.init_heap[j]
                if target == 1:
                    self.init_heap[i + addition] = current
                elif target == 2:
                    current = self.modification_requests[self.current_mod_request]
                    self.init_heap[i + addition] = current % MOD
                else:
                    current = self.modification_requests[self.current_mod_request] % MOD ** x
                    self.init_heap[i + addition] = current
                self.current_mod_request = (self.current_mod_request + 1) % len(self.modification_requests)

        return current

    def handle_request4(self, i: int, j: int, x: int, y: int) -> int:
        additions = [1 if j >= i and j < j + x else 0 for j in range(len(self.init_heap))]
        def powmod(p: int, pow: int) -> int:
            res = self.init_heap[j] + 1
            for _ in range(pow):
                res = (res * self.init_heap[j]) % MOD
            return res

        values = [powmod(1 << p, self.init_heap[j]) for p in range(1, x + 1) if additions[p - 1]]
        if additions[0] == 1:
            moneys = map(lambda b: powmod(1 << (x-p), MOD-2) * sum(b % MOD for b in values) % MOD, itertools.combinations([0, INT_MAX], x))
            results = [tmp % y for tmp in moneys]
