from typing import List
from typing import Tuple
from typing import NamedTuple

class Chai(NamedTuple):
    number: int
    x: int
    left: int
    right: int
    c: int
    d: int

def calculate_time(start_chai: Chai, end_chai: Chai, travel_chais: List[Chai]) -> int:
    n = len(travel_chais)
    min_time = float('inf')

    for i in range(n + 1):
        time = 0
        if i == 0:
            time += abs(start_chai.x - travel_chais[i].x) + (start_chai.left if start_chai.x < travel_chais[i].x else 0)
        elif i == n:
            time += abs(start_chai.x - travel_chais[i - 1].x) + (start_chai.right if start_chai.x > travel_chais[i - 1].x else 0)
        else:
            time += abs(start_chai.x - travel_chais[i].x) + (start_chai.left if start_chai.x < travel_chais[i].x else 0)
            time += abs(travel_chais[i].x - travel_chais[i - 1].x) + (travel_chais[i - 1].left if travel_chais[i - 1].x < travel_chais[i].x else 0)
            time += abs(travel_chais[i - 1].x - end_chai.x) + (end_chai.left if end_chai.x < travel_chais[i - 1].x else 0)

        if i == 0:
            time += travel_chais[0].d + travel_chais[0].c
        elif i == n:
            time += travel_chais[-1].d + travel_chais[-1].c
        else:
            time += travel_chais[i].c

        if i != 0:
            time += abs(start_chai.x - travel_chais[i - 1].x)
        if i != n:
            time += travel_chais[i + 1].d + travel_chais[i + 1].c + (travel_chais[i + 1].d if start_chai.x > travel_chais[i + 1].x else 0)

        min_time = min(min_time, time)

    return min_time

def solve(m: int, s: int, e: int, chairs: List[int], x: List[int], a: List[int], b: List[int], c: List[int], d: List[int]) -> int:
    travel_chais = []
    left_chais = []
    right_chais = []
    for i in range(m):
        travel_chais.append(Chai(i + 1, x[i], c[i] + d[i], b[i] + a[i], a[i] + b[i], c[i] + b[i] + a[i]))
        if i > 0:
            if x[i - 1] < x[i]:
                right_chais.append(travel_chais[i - 1])
            if x[i] < x[i + 1]:
                left_chais.append(travel_chais[i])

    left_chais.sort(key=lambda x: x.x)
    travel_chais.sort(key=lambda x: x.x)
    right_chais.sort(key=lambda x: x.x)

    return calculate_time(Chai(s, 0, x[s], 0, 0, 0), Chai(e, 0, 0, 0, 0, 0), travel_chais)

if __name__ == "__main__":
    n, s, e = map(int, input().split())
    x = list(map(int, input().split()))
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    c = list(map(int, input().split()))
    d = list(map(int, input().split()))
    print(solve(n, s, e, len(x), x, a, b, c, d))
