def find_smallest_number(K, base):
    lo, hi = 0, K + 1
    while lo < hi:
        mid = (lo + hi) // 2
        digits = list(str(mid + K))
        found = True
        for digit in digits:
            if int(digit) < 0 or int(digit) >= base:
                found = False
                break
        if found:
            if is_power_of_2(mid):
                hi = mid
            else:
                lo = mid + 1
        else:
            lo = mid + 1
    return (lo + K) % MOD

