import heapq
import collections

def dijkstra(graph, start):
    distance = {vertex: float('inf') for vertex in graph.keys()}
    distance[start] = 0
    queue = collections.deque([(0, start)])
    visited = set()

    while queue:
        current_dist, current_vertex = heapq.heappop(queue)
        if current_vertex in visited:
            continue
        visited.add(current_vertex)

        for neighbor, weight in graph[current_vertex].items():
            total_dist = current_dist + weight
            if total_dist < distance[neighbor]:
                distance[neighbor] = total_dist
                heapq.heappush(queue, (total_dist, neighbor))

    return distance

def shortest_path(graph, start, end):
    distance = dijkstra(graph, start)
    return distance.get(end, float('inf'))

