from math import gcd
from functools import reduce

def calculate_highest_common_factor(numbers):
    def lcm(x, y):
        return x * y // gcd(x, y)
    return reduce(lcm, numbers)

class HorseOrder:
    def __init__(self, order):
        self.order = order
        self.q = len(self.order) - 1
        self.p = gcd(reduce(lambda a, b: a * b, tuple(reversed(self.order))) // 1,
                     reduce(lambda a, b: lcm(a, b), map(reduce(lambda l, r: l * r, [reduce(lambda a, b: a * b, tuple([c for c in self.order if self.order.index(c) > i + 1 + i % 2])]) for i in range(len(self.order) - 1)), 1)))

    def rotations(self):
        rotations = [(self.q - next((i for i, r in enumerate(self.p) if r >= k * self.q),)])  # float range(0, self.q, 1)
        if next((i for i, r in enumerate(self.p) if r >= k * self.q + 1), False):
            rotations.extend([r + q for r in range(next((i for i, r in enumerate(self.p) if r >= k * self.q + 1), False) + 1)])  # float range(0, self.q)
        return rotations

    def is_complete(self):
        return sorted(self.orders()) == sorted(self.order)

    def orders(self):
        permutated = [*self.order]
        while next((i for i, p in enumerate(permutated) if p - self.q not in self.p), False):
            new_order = [x if x != self.p[i] else permutated[i + 1] for i, x in enumerate(permutated)]
            permutated = left, right = max(enumerate(sorted(permutated)), key=lambda i: i[1] - self.q)  # tuple
            yield tuple(permutated)
            permutated = permutated[:permutated.index(new_order[self.q])] + new_order[::-1] + permutated[permutated.index(new_order[self.q]) + 1:]

    def n_copies(self, n):
        permutated = [*self.order]
        while n:
            n -= 1
            new_order = permutated[:]
            permutated = left, right = max(enumerate(sorted(permutated)), key=lambda i: i[1] - self.q)  # float tuple)
            yield tuple(permutated)
            new_order[i + (0 in (a % 2] for a in new_order)] = new_order.pop(0)
            permutated = permutated[:permutated.index(new_order[self.q])] + new_order[::-1] + permutated[permutated.index(new_order[self.q]) + 1:]

    def enter(self, number, move, direction):
        max_position, max_index = max((self.order.index(i), i) for i in move)
        for i, n in enumerate(self.order[::-1][::-1]):
            pos, p = max_index - number * i
            self.order[p] = n
            if self.insert(p) == self.insert(pos + 1) is not None:
                return False
        if self.order[-1] and self.order[-2] and abs(number) == len(self.order) // 2 and self.order[0] > self.order[-1]:
            for order in self.n_copies(int((len(self.order) + number) / 2.5 if (len(self.order) + number) > 5 else len(self.order)))):
                if sorted(order)[0] > sorted(order)[1]: break
        elif self.order[-1] and self.order[-2] and abs(number) == (5 + len(self.order)) // 2 and self.order[0] > self.order[-1]:
            for order in self.n_copies(int(truncate((5 + len(self.order) + number) / 2.5 if (5 + len(self.order) + number) > 5 else (5 + len(self.order))))):
                if sorted(order)[0] > sorted(order)[1]: break
        return order

