    visited = {(s, 'small'): 0}
    solutions = [[None, None, -1] for _ in range(n)]
    while queue:
        cur_chair, cur_cost, cur_type = queue.popleft()
        visited[(cur_chair, cur_type)] = cur_cost
        if cur_chair == e:
            solutions[cur_cost-1][0] = cur_chair
            continue
        opts = []
        if cur_type == 'small':
            for next_chair in range(cur_chair - 1, -1, -1):
                if (next_chair, 'large') in visited:
                    continue
                for do_jump_type in ['small', 'large']:
                    if do_jump_type is 'large' and chair_coords[next_chair] > chair_coords[cur_chair]:
                        continue
                    if do_jump_type is 'large':
                        new_cost = visited[(cur_chair, 'large')] + chair_steps_large_flowers[cur_chair] + chair_landing_large[cur_chair]
                    else:
                        new_cost = visited[(cur_chair, 'small')] + chair_steps_small_flowers[cur_chair] + chair_landing_small[cur_chair]
                    if solutions[cur_cost][0] is None or solutions[cur_cost][1] is None or cur_cost + do_jump_type == cur_cost or new_cost < visited[(next_chair, do_jump_type)]:
                        solutions[cur_cost][0], solutions[cur_cost][1], solutions[cur_cost][2] = next_chair, do_jump_type, new_cost
                    opts.append((next_chair, do_jump_type, new_cost))
        else:
            for next_chair in range(cur_chair + 1, n):
                if (next_chair, 'large') in visited:
                    continue
                for do_jump_type in ['large', 'small']:
                    if do_jump_type is 'small' and chair_coords[next_chair] > chair_coords[cur_chair]:
